Write the commit message for this change.

Recent commit subjects, newest first:
- Describe the module in a README
- Add a todo list module

The staged diff (what the commit takes):
diff --git a/todo.js b/todo.js
index 6fa38b3..7bf8997 100644
--- a/todo.js
+++ b/todo.js
@@ -7,3 +7,8 @@ export function done(list, i) {
   list[i].done = true;
   return list;
 }
+
+export function remove(list, i) {
+  list.splice(i, 1);
+  return list;
+}

